The radio buttons created with radioButtons() don't work well with screen readers. I tired both with Orca and ChromeVox and neither of them read their label. 

To see the difference, this code creates two groups of radio buttons. Launch the app in Chrome with ChromeVox installed and navigate between them with tab. 

The when navigating to the first one it speaks "selected normal radio button selected" which means that there is no context of that "normal" means. When navigating to the second one it speaks "Distribution type radio button group normal radio button selected", which lets the user hear the context of the radio button.

```r
aria_radio <-  function (inputId, label, choices = NULL, selected = NULL, inline = FALSE, 
                         width = NULL, choiceNames = NULL, choiceValues = NULL) {
  args <- shiny:::normalizeChoicesArgs(choices, choiceNames, choiceValues)
  selected <- shiny::restoreInput(id = inputId, default = selected)
  selected <- if (is.null(selected)) 
    args$choiceValues[[1]]
  else as.character(selected)
  if (length(selected) > 1) 
    stop("The 'selected' argument must be of length 1")
  
  options <- aria_generateOptions(inputId, selected, inline, "radio",
                                     args$choiceNames, args$choiceValues)
  divClass <- "form-group shiny-input-radiogroup shiny-input-container"
  if (inline) shiny::divClass <- paste(divClass, "shiny-input-container-inline")
  
  
  shiny::tags$div(id = inputId, style = if (!is.null(width)) paste0("width: ", shiny::validateCssUnit(width), ";"),
                  class = divClass, role = "radiogroup", 
                  `aria-labelledby` = paste0(inputId, "label"),                                   # this is new
                  shiny::tags$label(label, class = "control-label", class = if (is.null(label)) "shiny-label-null", 
                                    `for` = inputId, 
                                    id = paste0(inputId, "label")                                         # this is also new.
                                    ),
                  options)
}

aria_generateOptions <- function (inputId, selected, inline, type = "checkbox", choiceNames, 
                                  choiceValues, session = shiny::getDefaultReactiveDomain()) {
  options <- mapply(choiceValues, choiceNames, FUN = function(value, 
                                                              name) {
    inputTag <- shiny::tags$input(type = type, name = inputId, 
                                  value = value)
    if (value %in% selected) {
      inputTag$attribs$checked <- "checked"
    } else {
    }
    
    if (type == "radio") {
      inputTag$attribs$role <- "radio"        # This is also needed
    }
      
    pd <- shiny:::processDeps(name, session)
    if (inline) {
      shiny::tags$label(class = paste0(type, "-inline"), inputTag, 
                        shiny::tags$span(pd$html, pd$deps))
    }
    else {
      shiny::tags$div(class = type, shiny::tags$label(inputTag, shiny::tags$span(pd$html, pd$deps)))
    }
  }, SIMPLIFY = FALSE, USE.NAMES = FALSE)
  shiny::div(class = "shiny-options-group", options)
}


ui <- fluidPage(
  radioButtons("dist", "Distribution type:",
               c("Normal" = "norm",
