Somewhat related to #1516 
One of the common uses for a modal is simply as a more elegant alert. Suppose a Shiny app is a form, and a modal is used to give feedback to user when they submit the form. It would be nice to conditionally style the modal depending on whether the user correctly or incorrectly filled out the form. Currently one can style the content in the form as they would any other content in Shiny, but they can't style the modal itself programmatically without a good deal of additional effort. Below is an overly simple example that hopefully illustrates why a class parameter would be useful:

```{R}
library(shiny)

ui <- fluidPage(
  tags$style(
    HTML(
      ".error {
      background-color: red;
      }
      .success {
      background-color: green;
      }"
  )
    ),
  textInput("test", "Add Text"),
  actionButton("btn1", "Press Me (regular modal)"),
  actionButton("btn2", "Press Me (custom modal)")
    )

# add class parameter
modalDialog2 <-
  function (...,
            title = NULL,
            footer = modalButton("Dismiss"),
            size = c("m", "s", "l"),
            easyClose = FALSE,
            fade = TRUE,
            class)
  {
    size <- match.arg(size)
    cls <- if (fade)
      "modal fade"
    else
      "modal"
    
    div(
      id = "shiny-modal",
      class = cls,
      tabindex = "-1",
      `data-backdrop` = if (!easyClose)
        "static",
      `data-keyboard` = if (!easyClose)
        "false",
      div(
        class = "modal-dialog",
        class = switch(size,
                       s = "modal-sm", m = NULL, l = "modal-lg"),
        div(
          class = if (!missing(class))
            paste(class, "modal-content")
          else
            "modal-content",
          if (!is.null(title))
            div(class = "modal-header", tags$h4(class = "modal-title",
                                                title)),
          div(class = "modal-body", ...),
          if (!is.null(footer))
            div(class = "modal-footer", footer)
        )
      ),
      tags$script("$('#shiny-modal').modal().focus();")
    )
  }

server <- function(input, output, session) {
  observeEvent(input$btn1, {
    if (input$test == "") {
      showModal(modalDialog(
        title = "Error",
        size = "s",
        div("Don't forget to enter a value",
            style = "background-color: red;")
      ))
    } else {
      showModal(modalDialog(
        title = "Success",
        size = "s",
        div("You entered a value",
            style = "background-color: green;")
      ))
    }
  })
  observeEvent(input$btn2, {
    if (input$test == "") {
      showModal(
        modalDialog2(
          title = "Error",
          size = "s",
          "Don't forget to enter a value",
          class = "error"
        )
      )
    } else {
      showModal(
        modalDialog2(
          title = "Success",
          size = "s",
          "You entered a value",
          class = "success"
        )
      )
    }
  })
}

shinyApp(ui = ui, server = server)
```

