  ui = fluidPage(
    plotOutput("p", brush = "brush", width = "400px"),
    verbatimTextOutput("showcount")
  ),
  server = function(input, output) {
    dataWithSelection <- reactive({
      brushedPoints(mtcars, input$brush, allRows = TRUE)
