    downloadLink('download'),
    textOutput('txt')
  ),
  server = function(input, output) {
    output$download <- downloadHandler(
      'foo.txt',
      function(file) {
        # domain is NULL
        domain <- getDefaultReactiveDomain()
        print(domain)

        writeLines(format(domain), con = file)
      }
    )

